{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions. In 2020, approximately 3.3 billion USD was invested globally for malaria interventions, falling short of the targeted 6.8 billion USD set by the GTS, increasing the financial gap between desirable and actual investment.",
      "reason": "The background describes the current state of knowledge (progress stalling, financing gap) and the uncertainty/need that models for optimization address."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets. This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The aim and general utility of such models are stated, but the importance and need for conducting the review itself are only implicitly conveyed; no explicit statement of why this review is needed is provided in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No similar prior systematic reviews are mentioned or cited anywhere in the retrieved evidence, so there is no indication that an update or replication requiring justification exists."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of optimization models for resource allocation, not a review of intervention effects; no mechanism-of-action description requirement applies based on the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines modelling studies rather than evaluating intervention effects directly; no logic model is presented or required by the retrieved evidence."
    }
  ],
  "confidence": 72
