      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of optimization models for malaria resource allocation, not a review of intervention effects; no planned intervention-effect comparisons are reported, so PICO-style comparison statements do not apply."
    }
