    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria: (1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024; (3) Studies were included irrespective of the targeted geographical regions; (4) Studies were included irrespective of the population subgroups; (5) Studies containing an optimization model (mathematical or statistical); (6) All studies with human Plasmodium species; (7) Studies with two or more interventions; (8) Cost data were used in combination with the model outputs; (9) Outcomes/health benefits were clearly stated and/or measured.",
      "reason": "Eligibility criteria cover study design (optimization models), population (human Plasmodium, any subgroup), setting (any region), interventions (two or more), and outcome requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "(1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024",
      "reason": "Report characteristics are specified: publication status (peer-reviewed), language (English), and dissemination date (before 30 June 2024); exclusions of non-English and pre-prints/grey literature are confirmed in text_9."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_9",
      "quote": "The following records were excluded: (1) Editorials, commentaries, opinion papers, conference abstracts, media reports, letters, bulletins, pre-prints, grey literature; (2) Non-English language studies; (3) Systematic reviews, meta-analyses.",
      "reason": "The review does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported; the PRISMA diagram (figure_3) lists exclusion reasons (e.g., 'No optimisation model') but not this distinction."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": "text_10",
      "quote": "A narrative synthesis of the study characteristics was performed.",
      "reason": "A narrative synthesis is reported, but no explicit groups for each synthesis are specified and linked to the review objectives' comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "Studies with two or more interventions; Cost data were used in combination with the model outputs",
      "reason": "Notable restrictions (e.g., English only, two or more interventions, cost data required) are stated but no rationales for these restrictions are provided."
    }
